    ctx.strokeStyle='#d8d2c2';ctx.lineWidth=3;ctx.beginPath();ctx.arc(10,-93,6,-1.2,1.2);ctx.stroke();
  }else{
    ctx.save();ctx.translate(0,-88);ctx.rotate(1.4);
    ctx.fillStyle='#d8d2c2';ctx.fillRect(-10,-9,20,18);ctx.restore();
    ctx.fillStyle='rgba(150,110,70,.5)';ctx.beginPath();ctx.ellipse(18,-82,14,4,0,0,TAU);ctx.fill();
  }
  if(P.specs==='stand'){
    ctx.strokeStyle='#c9c2b2';ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(-16,-90,5,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(-5,-90,5,0,TAU);ctx.stroke();
  }
  ctx.restore();
  if(P.specs==='floor'){
    ctx.save();ctx.translate(880,806);ctx.rotate(-0.3);
    ctx.strokeStyle='#c9c2b2';ctx.lineWidth=2.4;
    ctx.beginPath();ctx.arc(-7,0,6,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(7,0,6,0,TAU);ctx.stroke();
    ctx.restore();
  }
  if(P.cap==='floor'){
    ctx.fillStyle='#ece2cc';ctx.beginPath();ctx.ellipse(1060,820,30,12,0.3,0,TAU);ctx.fill();
  }
  if(P.shawlFloor&&t<101800){
    ctx.fillStyle='#9a93a6';ctx.beginPath();ctx.ellipse(1440,824,52,16,-0.2,0,TAU);ctx.fill();
    ctx.fillStyle='#8b849a';ctx.beginPath();ctx.ellipse(1420,816,26,10,0.3,0,TAU);ctx.fill();
  }
  // wardrobe (far right)
  ctx.save();ctx.translate(1500,760);
  ctx.fillStyle='#4f3a22';ctx.fillRect(-64,-330,150,330);
  ctx.fillStyle='#3a2a16';ctx.fillRect(-56,-318,64,306);
  const wd=P.wardrobe;
  if(wd>0.03){ctx.fillStyle='#171310';ctx.fillRect(-56+64*(1-wd),-318,64*wd,306);}
  ctx.save();ctx.translate(-56,0);ctx.transform(1-wd*0.7,0,0.1*wd,1,0,0);
  ctx.fillStyle='#5d4527';ctx.fillRect(0,-318,64,306);
  ctx.fillStyle='#c9b98e';ctx.beginPath();ctx.arc(54,-160,4.4,0,TAU);ctx.fill();
  ctx.restore();
  ctx.fillStyle='#5d4527';ctx.fillRect(12,-318,66,306);
  ctx.fillStyle='#c9b98e';ctx.beginPath();ctx.arc(22,-160,4.4,0,TAU);ctx.fill();
  ctx.restore();
  // cool dimming laid over everything
  ctx.fillStyle='rgba(34,44,66,'+ (dim*0.55) +')';ctx.fillRect(0,0,W,H);
  if(o.motes)motes(t,14,{x:220,y:340,w:420,h:420},0.4);
}

